class ImpactEngine:
  async def analyze_impact(self, diff: CommitDiff, base_sha: str) -> ImpactResult:
    factors = await self._calculate_risk_factors(diff)
    subgraph = await self.dep_graph.get_downstream_impact(diff.service)
    semantic = await self.retrieval.get_semantic_risk(diff)
    return self._synthesize_risk_score(factors, subgraph, semantic)

