def generate_explanation(text):
  inputs = tokenizer(text, return_tensors='pt')
  outputs = model.generate(
    inputs.input_ids,
    max_length=200
  )
  return tokenizer.decode(outputs[0])

def get_cart_totals(cart_id):
  return db.session.query(
    db.func.sum(Product.price * CartItem.quantity),
    db.func.sum(CartItem.quantity)
  ).join(CartItem, Product.id == CartItem.product_id).filter(CartItem.cart_id == cart_id).first()

def fetch_json(url: str) -> dict:
  req = urllib.request.Request(url, headers={'User-Agent': 'WeatherVision/1.0'})
  with urllib.request.urlopen(req, timeout=15) as resp:
    return json.loads(resp.read().decode('utf-8'))

